def find_exactly_one_pair(nums):
    from collections import Counter

    if len(nums) < 2:
        return False

    counts = Counter(nums)
    has_pair = False
    pair_value = None
    unique_elements = []

    for num, count in counts.items():
        if count > 1:
            has_pair = True
            if pair_value is None:
                pair_value = num
            else:
                # If we already have a pair, this second occurrence doesn't matter
                # as long as there's exactly one pair.
                pass

    if not has_pair:
