def sum_of_multiples(n):
    def sum_of_multiples_by_m(m, limit):
        if m == 1:
            return limit - 1
        # Use inclusion-exclusion principle:
        # sum = sum of multiples of m + sum of multiples of n
        #       - sum of multiples of lcm(m, n)
        lcm = m * n // gcd(m, n)
        return sum_of_multiples_by_m(m, limit) + sum_of_multiples_by_m(n, limit) - sum_of_multiples_by_m(lcm, limit)

    def sum_of_multiples_by_m(m, limit):
        if m == 1:
            return limit - 1
        # Number of multiples of m below limit: floor((limit - 1) / m)
        count = (limit - 1) // m
        return m * count * (count + 1) // 2

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    return sum_of_multiples_by_m(3, n) + sum_of_multiples_by_m(5, n) - sum_of_multiples_by_m(15, n)
