def pad_binary(num, length):
    if num == 0:
        return '0' * length

    # Compute binary length without using built-in bin
    if num < 0:
        raise ValueError("num must be non-negative")

    binary_len = 0
    temp = num
    while temp > 0:
        temp >>= 1
        binary_len += 1

    # If length is less than binary length, return without padding
    if length < binary_len:
        return str(num)

    # Pad with leading zeros
    padded = '0' * (length - binary_len) + str(num)
    return padded
