def find_triplet(numbers, target):
    if len(numbers) < 3:
        return []

    # Sort the array to enable two-pointer technique
    numbers.sort()

    n = len(numbers)
    for i in range(n - 2):
        # Skip duplicate values for the first element to avoid redundant checks
        if i > 0 and numbers[i] == numbers[i - 1]:
            continue

        left, right = i + 1, n - 1
        current_sum = numbers[i]

        # Use two pointers to find a pair that sums to target - current_sum
        while left < right:
            pair_sum = numbers[left] + numbers[right]

            if pair_sum == target - current_sum:
                return [current_sum, numbers[left], numbers[right]]
            elif pair_sum < target - current_sum:
                left += 1
            else:
                right -= 1

