def is_valid_expression(expression):
    if not expression:
        return True

    # Mapping from opening bracket to its weight
    bracket_weights = {
        '(': 2,
        '{': 3,
        '[': 5
    }

    # Stack to track opening brackets and their weights
    stack = []

    for char in expression:
        if char in bracket_weights:
            # Opening bracket
            weight = bracket_weights[char]
            stack.append((char, weight))
        else:
            # Closing bracket
            if not stack:
                return False

            last_open, last_weight = stack.pop()
            if last_weight != bracket_weights[char]:
                return False

    # Check if all opening brackets are closed
    if stack:
        return False

    return True
