def minOperations(str1, str2):
    m, n = len(str1), len(str2)
    # Create a DP table where dp[i][j] = min operations to convert str1[:i] to str2[:j]
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Initialize base cases
    for i in range(m + 1):
        dp[i][0] = i  # Delete all characters of str1 to get empty str2
    for j in range(n + 1):
        dp[0][j] = j  # Insert all characters of str2 to get empty str1

    # Fill DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if str1[i - 1] == str2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]  # No operation needed
            else:
                dp[i][j] = 1 + min(
                    dp[i - 1][j],      # Delete str1[i-1]
                    dp[i][j - 1],      # Insert str1[i-1]
                    dp[i - 1][j - 1]   # Replace str1[i-1] with str2[j-1]
                )

    return dp[m][n]
