def firstMissingPositive(nums):
    if not nums:
        return 1

    n = len(nums)
    # Use the array itself as a hint: place each number at index |x| - 1 if it's in the valid range [1, n]
    for i in range(n):
        # Only consider numbers between 1 and n
        x = abs(nums[i])
        if 1 <= x <= n:
            # Place the absolute value at the correct index
            nums[x - 1] = -abs(nums[x - 1])

    # Now scan from 1 to n to find the first missing positive
    for i in range(1, n + 1):
        if nums[i - 1] > 0:
            return i

    # If all positions 1..n are filled with positive numbers, then n+1 is missing
    return n + 1
